import base64, os, sys, subprocess

base_dir = '/root/multi_agent_pipeline'

files = [
    ('src/tools/workspace-config.ts', ''),
    ('src/tools/pipeline.ts', ''),
    ('src/tools/pipeline-continue.ts', ''),
    ('scripts/deploy.sh', ''),
    ('docs/orchestrator-SOUL.md', ''),
]

for path, b64 in files:
    full_path = os.path.join(base_dir, path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    try:
        content = base64.b64decode(b64).decode('utf-8')
        with open(full_path, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f'  OK {path}')
    except Exception as e:
        print(f'  FAIL {path}: {e}')

print()
print('=== Building... ===')
os.chdir(base_dir)
r = subprocess.run(['npm', 'run', 'build'], capture_output=True, text=True)
if r.returncode != 0:
    print('BUILD FAILED:')
    print(r.stderr[-1500:])
    sys.exit(1)

print('=== BUILD OK. Running deploy.sh... ===')
r = subprocess.run(['bash', 'scripts/deploy.sh'], capture_output=True, text=True)
out = r.stdout
if len(out) > 3000: out = out[-3000:]
print(out)
if r.returncode != 0:
    err = r.stderr
    if len(err) > 1500: err = err[-1500:]
    print(f'DEPLOY FAILED: {err}')
    sys.exit(1)

print('=== DEPLOY OK ===')
print('Restart: openclaw gateway restart')
